CREATE TABLE IF NOT EXISTS employees (id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,name TEXT NOT NULL,email TEXT DEFAULT '',role TEXT NOT NULL DEFAULT 'member',status TEXT NOT NULL DEFAULT 'active',salary INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS invoices (id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,client_id TEXT DEFAULT '',number TEXT NOT NULL,description TEXT DEFAULT '',amount INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'draft',due_date TEXT DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,title TEXT NOT NULL,message TEXT DEFAULT '',read INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,action TEXT NOT NULL,entity TEXT DEFAULT '',entity_id TEXT DEFAULT '',metadata TEXT DEFAULT '',created_at TEXT NOT NULL,FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_audit_owner ON audit_logs(owner_id,created_at);
